-- Exact E owner-edit/lock subset from internal5e6c72fd PACKET-IP, 8 November 2026.
-- Proposed fixture only; no native schema adoption and no Capture claim. Group
-- E is not embedded yet, so the embedded metadata_owner_fields gains its two
-- presence columns here, the edit owner/receipt/history tables are created and
-- catalog_entities gains the explicit saved show-settings presence marker.
ALTER TABLE metadata_owner_fields ADD COLUMN value_present INTEGER NOT NULL DEFAULT 1 CHECK(typeof(value_present)='integer' AND value_present IN(0,1) AND (value_present=1 OR value=''));

ALTER TABLE metadata_owner_fields ADD COLUMN automatic_present INTEGER NOT NULL DEFAULT 1 CHECK(typeof(automatic_present)='integer' AND automatic_present IN(0,1) AND (automatic_present=1 OR automatic_value=''));

CREATE TABLE metadata_edit_owners(
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 entity_id INTEGER UNIQUE REFERENCES catalog_subjects(id),
 person_id INTEGER UNIQUE REFERENCES catalog_people(id),
 kind TEXT NOT NULL CHECK(kind IN('item','show','season','album','artist','book','person','collection')),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),
 retired_ms INTEGER CHECK(retired_ms IS NULL OR retired_ms>=0),
 command_incarnation BLOB NOT NULL CHECK(length(command_incarnation)=16),
 last_command_sequence INTEGER NOT NULL DEFAULT 0 CHECK(last_command_sequence>=0),
 acknowledged_command_sequence INTEGER NOT NULL DEFAULT 0 CHECK(acknowledged_command_sequence>=0),
 receipt_reclaim_after_sequence INTEGER NOT NULL DEFAULT 0 CHECK(receipt_reclaim_after_sequence>=0),
 receipt_reclaim_due_ms INTEGER CHECK(receipt_reclaim_due_ms IS NULL OR receipt_reclaim_due_ms>=0),
 reclaim_command_sequence INTEGER CHECK(reclaim_command_sequence IS NULL OR reclaim_command_sequence>0),
 reclaim_operation_id BLOB CHECK(reclaim_operation_id IS NULL OR length(reclaim_operation_id)=16),
 reclaim_request_digest BLOB CHECK(reclaim_request_digest IS NULL OR length(reclaim_request_digest)=32),
 reclaim_applied_ms INTEGER CHECK(reclaim_applied_ms IS NULL OR reclaim_applied_ms>=0),
 reclaim_result_digest BLOB CHECK(reclaim_result_digest IS NULL OR length(reclaim_result_digest)=32),
 reclaim_captured_ack INTEGER CHECK(reclaim_captured_ack IS NULL OR reclaim_captured_ack>=0),
 reclaim_old_cursor INTEGER CHECK(reclaim_old_cursor IS NULL OR reclaim_old_cursor>=0),
 reclaim_removed_count INTEGER CHECK(reclaim_removed_count IS NULL OR reclaim_removed_count>=0),
 reclaim_removed_bytes INTEGER CHECK(reclaim_removed_bytes IS NULL OR reclaim_removed_bytes>=0),
 reclaim_result_cursor INTEGER CHECK(reclaim_result_cursor IS NULL OR reclaim_result_cursor>=0),
 reclaim_no_next INTEGER CHECK(reclaim_no_next IS NULL OR reclaim_no_next IN(0,1)),
 UNIQUE(id,command_incarnation),
 CHECK((entity_id IS NULL)<>(person_id IS NULL)),
 CHECK((kind='person')=(person_id IS NOT NULL)),
 CHECK(receipt_reclaim_after_sequence<=acknowledged_command_sequence AND acknowledged_command_sequence<=last_command_sequence),
 CHECK(((reclaim_command_sequence IS NULL)=(reclaim_operation_id IS NULL)) AND ((reclaim_command_sequence IS NULL)=(reclaim_request_digest IS NULL)) AND ((reclaim_command_sequence IS NULL)=(reclaim_applied_ms IS NULL)) AND ((reclaim_command_sequence IS NULL)=(reclaim_result_digest IS NULL)) AND ((reclaim_command_sequence IS NULL)=(reclaim_captured_ack IS NULL)) AND ((reclaim_command_sequence IS NULL)=(reclaim_old_cursor IS NULL)) AND ((reclaim_command_sequence IS NULL)=(reclaim_removed_count IS NULL)) AND ((reclaim_command_sequence IS NULL)=(reclaim_removed_bytes IS NULL)) AND ((reclaim_command_sequence IS NULL)=(reclaim_result_cursor IS NULL)) AND ((reclaim_command_sequence IS NULL)=(reclaim_no_next IS NULL))),
 CHECK(reclaim_command_sequence IS NULL OR (reclaim_command_sequence<=last_command_sequence AND reclaim_command_sequence-reclaim_captured_ack=1 AND reclaim_captured_ack<=acknowledged_command_sequence AND reclaim_old_cursor<=reclaim_result_cursor AND reclaim_result_cursor<=reclaim_captured_ack AND receipt_reclaim_after_sequence=reclaim_result_cursor AND (reclaim_no_next=0 OR reclaim_result_cursor=reclaim_captured_ack) AND (reclaim_removed_count<>0 OR reclaim_removed_bytes=0))),
 CHECK(typeof(id) IN('null','integer')),
 CHECK(typeof(entity_id) IN('null','integer')),
 CHECK(typeof(person_id) IN('null','integer')),
 CHECK(typeof(kind) IN('null','text')),
 CHECK(typeof(revision) IN('null','integer')),
 CHECK(typeof(retired_ms) IN('null','integer')),
 CHECK(typeof(command_incarnation) IN('null','blob')),
 CHECK(typeof(last_command_sequence) IN('null','integer')),
 CHECK(typeof(acknowledged_command_sequence) IN('null','integer')),
 CHECK(typeof(receipt_reclaim_after_sequence) IN('null','integer')),
 CHECK(typeof(receipt_reclaim_due_ms) IN('null','integer')),
 CHECK(typeof(reclaim_command_sequence) IN('null','integer')),
 CHECK(typeof(reclaim_operation_id) IN('null','blob')),
 CHECK(typeof(reclaim_request_digest) IN('null','blob')),
 CHECK(typeof(reclaim_applied_ms) IN('null','integer')),
 CHECK(typeof(reclaim_result_digest) IN('null','blob')),
 CHECK(typeof(reclaim_captured_ack) IN('null','integer')),
 CHECK(typeof(reclaim_old_cursor) IN('null','integer')),
 CHECK(typeof(reclaim_removed_count) IN('null','integer')),
 CHECK(typeof(reclaim_removed_bytes) IN('null','integer')),
 CHECK(typeof(reclaim_result_cursor) IN('null','integer')),
 CHECK(typeof(reclaim_no_next) IN('null','integer'))
);

CREATE TABLE metadata_edit_receipts(
 owner_id INTEGER NOT NULL,
 command_incarnation BLOB NOT NULL CHECK(length(command_incarnation)=16),
 command_sequence INTEGER NOT NULL CHECK(command_sequence>0),
 operation_id BLOB NOT NULL UNIQUE CHECK(length(operation_id)=16),
 request_digest BLOB NOT NULL CHECK(length(request_digest)=32),
 applied_ms INTEGER NOT NULL CHECK(applied_ms>=0),
 result_digest BLOB NOT NULL CHECK(length(result_digest)=32),
 command_kind TEXT NOT NULL CHECK(command_kind IN('field_edit','field_lock','field_restore')),
 field TEXT NOT NULL,
 result_count INTEGER NOT NULL DEFAULT 1 CHECK(result_count>0),
 accepted_revision INTEGER NOT NULL CHECK(accepted_revision>0),
 subject_revision INTEGER NOT NULL CHECK(subject_revision>0),
 value TEXT NOT NULL,
 value_present INTEGER NOT NULL CHECK(value_present IN(0,1)),
 automatic_value TEXT NOT NULL,
 automatic_present INTEGER NOT NULL CHECK(automatic_present IN(0,1)),
 locked INTEGER NOT NULL CHECK(locked IN(0,1)),
 changed INTEGER NOT NULL CHECK(changed IN(0,1)),
 effective_changed INTEGER NOT NULL CHECK(effective_changed IN(0,1)),
 history_id INTEGER REFERENCES metadata_owner_history(id),
 PRIMARY KEY(owner_id,command_incarnation,command_sequence),
 FOREIGN KEY(owner_id,command_incarnation) REFERENCES metadata_edit_owners(id,command_incarnation),
 CHECK((value_present=1 OR value='') AND (automatic_present=1 OR automatic_value='')),
 CHECK(locked=0 OR value_present=1),
 CHECK(effective_changed<=changed),
 CHECK(field='' OR result_count=1),
 CHECK(field<>'' OR (value='' AND automatic_value='' AND value_present=0 AND automatic_present=0 AND locked=0)),
 CHECK((changed=1)=(history_id IS NOT NULL)),
 CHECK(typeof(owner_id) IN('null','integer')),
 CHECK(typeof(command_incarnation) IN('null','blob')),
 CHECK(typeof(command_sequence) IN('null','integer')),
 CHECK(typeof(operation_id) IN('null','blob')),
 CHECK(typeof(request_digest) IN('null','blob')),
 CHECK(typeof(applied_ms) IN('null','integer')),
 CHECK(typeof(result_digest) IN('null','blob')),
 CHECK(typeof(command_kind) IN('null','text')),
 CHECK(typeof(field) IN('null','text')),
 CHECK(typeof(result_count) IN('null','integer')),
 CHECK(typeof(accepted_revision) IN('null','integer')),
 CHECK(typeof(subject_revision) IN('null','integer')),
 CHECK(typeof(value) IN('null','text')),
 CHECK(typeof(value_present) IN('null','integer')),
 CHECK(typeof(automatic_value) IN('null','text')),
 CHECK(typeof(automatic_present) IN('null','integer')),
 CHECK(typeof(locked) IN('null','integer')),
 CHECK(typeof(changed) IN('null','integer')),
 CHECK(typeof(effective_changed) IN('null','integer')),
 CHECK(typeof(history_id) IN('null','integer'))
) WITHOUT ROWID;

CREATE INDEX metadata_edit_receipt_history ON metadata_edit_receipts(history_id,owner_id) WHERE history_id IS NOT NULL;

CREATE TABLE metadata_edit_receipt_fields(
 owner_id INTEGER NOT NULL,
 command_incarnation BLOB NOT NULL CHECK(length(command_incarnation)=16),
 command_sequence INTEGER NOT NULL CHECK(command_sequence>0),
 ordinal INTEGER NOT NULL CHECK(ordinal>=0),
 field TEXT NOT NULL CHECK(length(field)>0),
 value TEXT NOT NULL,
 value_present INTEGER NOT NULL CHECK(value_present IN(0,1)),
 automatic_value TEXT NOT NULL,
 automatic_present INTEGER NOT NULL CHECK(automatic_present IN(0,1)),
 locked INTEGER NOT NULL CHECK(locked IN(0,1)),
 changed INTEGER NOT NULL CHECK(changed IN(0,1)),
 effective_changed INTEGER NOT NULL CHECK(effective_changed IN(0,1)),
 PRIMARY KEY(owner_id,command_incarnation,command_sequence,ordinal),
 UNIQUE(owner_id,command_incarnation,command_sequence,field),
 FOREIGN KEY(owner_id,command_incarnation,command_sequence) REFERENCES metadata_edit_receipts(owner_id,command_incarnation,command_sequence),
 CHECK((value_present=1 OR value='') AND (automatic_present=1 OR automatic_value='')),
 CHECK(locked=0 OR value_present=1),
 CHECK(effective_changed<=changed),
 CHECK(typeof(owner_id) IN('null','integer')),
 CHECK(typeof(command_incarnation) IN('null','blob')),
 CHECK(typeof(command_sequence) IN('null','integer')),
 CHECK(typeof(ordinal) IN('null','integer')),
 CHECK(typeof(field) IN('null','text')),
 CHECK(typeof(value) IN('null','text')),
 CHECK(typeof(value_present) IN('null','integer')),
 CHECK(typeof(automatic_value) IN('null','text')),
 CHECK(typeof(automatic_present) IN('null','integer')),
 CHECK(typeof(locked) IN('null','integer')),
 CHECK(typeof(changed) IN('null','integer')),
 CHECK(typeof(effective_changed) IN('null','integer'))
) WITHOUT ROWID;

CREATE TABLE metadata_owner_history_fields(
 history_id INTEGER NOT NULL REFERENCES metadata_owner_history(id),
 field TEXT NOT NULL,
 before_value TEXT NOT NULL,
 before_value_present INTEGER NOT NULL CHECK(before_value_present IN(0,1)),
 before_automatic TEXT NOT NULL,
 before_automatic_present INTEGER NOT NULL CHECK(before_automatic_present IN(0,1)),
 before_locked INTEGER NOT NULL CHECK(before_locked IN(0,1)),
 after_value TEXT NOT NULL,
 after_value_present INTEGER NOT NULL CHECK(after_value_present IN(0,1)),
 after_automatic TEXT NOT NULL,
 after_automatic_present INTEGER NOT NULL CHECK(after_automatic_present IN(0,1)),
 after_locked INTEGER NOT NULL CHECK(after_locked IN(0,1)),
 PRIMARY KEY(history_id,field),
 CHECK((before_value_present=1 OR before_value='') AND (before_automatic_present=1 OR before_automatic='')),
 CHECK((after_value_present=1 OR after_value='') AND (after_automatic_present=1 OR after_automatic='')),
 CHECK((before_locked=0 OR before_value_present=1) AND (after_locked=0 OR after_value_present=1)),
 CHECK(typeof(history_id) IN('null','integer')),
 CHECK(typeof(field) IN('null','text')),
 CHECK(typeof(before_value) IN('null','text')),
 CHECK(typeof(before_value_present) IN('null','integer')),
 CHECK(typeof(before_automatic) IN('null','text')),
 CHECK(typeof(before_automatic_present) IN('null','integer')),
 CHECK(typeof(before_locked) IN('null','integer')),
 CHECK(typeof(after_value) IN('null','text')),
 CHECK(typeof(after_value_present) IN('null','integer')),
 CHECK(typeof(after_automatic) IN('null','text')),
 CHECK(typeof(after_automatic_present) IN('null','integer')),
 CHECK(typeof(after_locked) IN('null','integer'))
) WITHOUT ROWID;

-- E: explicit saved show-settings presence; all-false saved settings override
-- library episode numbering, while absent settings inherit. The point owner CAS
-- advances show_settings_revision on first save even when booleans remain zero.
ALTER TABLE catalog_entities ADD COLUMN show_settings_present INTEGER NOT NULL DEFAULT 0 CHECK(typeof(show_settings_present)='integer' AND show_settings_present IN(0,1) AND (show_settings_present=0 OR kind=2));
